from pathlib import Path
import base64

BASE = "45f5be8"

def read(path):
    p = Path(path)
    if not p.exists():
        raise SystemExit(f"Missing {path}. Run from the sepulchria-portal repo root.")
    return p.read_text(encoding="utf-8")

def write(path, text):
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding="utf-8")
    print("✓", path)

def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected 1 match, found {count}. Expected commit {BASE}.")
    return text.replace(old, new, 1)

PAYLOADS = {'components/notifications/notification-bell.tsx': '', 'app/(portal)/admin/notifications/actions.ts': '', 'app/(portal)/admin/notifications/page.tsx': ''}
for path, data in PAYLOADS.items():
    if Path(path).exists():
        raise SystemExit(f"{path} already exists. Stop before applying twice.")
    write(path, base64.b64decode(data).decode("utf-8"))

